CREATE TABLE IF NOT EXISTS ly_do (id VARCHAR(40) PRIMARY KEY, ma_ly_do VARCHAR(40) UNIQUE NOT NULL, ten_ly_do VARCHAR(250) NOT NULL CHECK (length(trim(ten_ly_do))>0), ghi_chu TEXT, trang_thai VARCHAR(30) NOT NULL DEFAULT 'DANG_SU_DUNG' CHECK (trang_thai IN ('DANG_SU_DUNG','NGUNG_SU_DUNG')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, created_by VARCHAR(20) REFERENCES users(ma_nguoi_dung) ON DELETE SET NULL, updated_by VARCHAR(20) REFERENCES users(ma_nguoi_dung) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS ly_do_chuc_nang (id VARCHAR(40) PRIMARY KEY, ly_do_id VARCHAR(40) NOT NULL REFERENCES ly_do(id) ON DELETE CASCADE, chuc_nang VARCHAR(60) NOT NULL CHECK (chuc_nang IN ('DOI_TRANG_THAI_NGUYEN_LIEU','DOI_TRANG_THAI_CONG_THUC','DOI_TRANG_THAI_NHA_CUNG_CAP')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(ly_do_id,chuc_nang));
CREATE INDEX IF NOT EXISTS ix_ly_do_chuc_nang_lookup ON ly_do_chuc_nang(chuc_nang,ly_do_id);
